using System.Security.Cryptography; using System.Text;
using Archy.Features.Graph.ReadGraphRevision; using Archy.Features.Placement.ClusterRevisions; using Archy.SharedKernel.Primitives;
namespace Archy.Features.Placement.ComputeModuleCohesion;
/// <summary>Materializes weighted graph communities as immutable cluster membership plus explainable internal/external cohesion.</summary>
public sealed class ModuleCohesionCalculator : IModuleCohesionCalculator
{
 public ModuleCohesionResult Calculate(GraphRevisionSnapshot graph,IReadOnlyList<DetectedCommunity> communities,string algorithmVersion){ArgumentNullException.ThrowIfNull(graph);ArgumentNullException.ThrowIfNull(communities);ArgumentException.ThrowIfNullOrWhiteSpace(algorithmVersion);if(communities.Count==0||communities.Any(c=>c is null||string.IsNullOrWhiteSpace(c.CommunityKey)||c.MemberStableIds is null||c.MemberStableIds.Count==0||c.MemberStableIds.Any(string.IsNullOrWhiteSpace))||communities.Select(c=>c.CommunityKey).Distinct(StringComparer.Ordinal).Count()!=communities.Count)throw new ArgumentException("Cohesion requires uniquely named non-empty communities.",nameof(communities));var nodes=graph.Nodes.Select(n=>n.StableId).ToHashSet(StringComparer.Ordinal);var all=communities.SelectMany(c=>c.MemberStableIds).ToArray();if(all.Distinct(StringComparer.Ordinal).Count()!=all.Length||all.Any(id=>!nodes.Contains(id)))throw new ArgumentException("Communities must partition known graph nodes without overlap.",nameof(communities));var facts=new List<ClusterFact>();var metrics=new List<ModuleCohesionMetric>();foreach(var c in communities.OrderBy(c=>c.CommunityKey,StringComparer.Ordinal)){var members=c.MemberStableIds.ToHashSet(StringComparer.Ordinal);double inside=0,outside=0;foreach(var e in graph.Edges){var source=members.Contains(e.SourceStableId);var target=members.Contains(e.TargetStableId);if(!source&&!target)continue;var w=Math.Clamp(e.Confidence,0d,1d);if(source&&target)inside+=w;else outside+=w;}var cohesion=inside+outside==0?0d:Math.Round(inside/(inside+outside),6,MidpointRounding.AwayFromZero);metrics.Add(new(c.CommunityKey,members.Count,inside,outside,cohesion));facts.Add(new ClusterFact(c.CommunityKey,[.. members.OrderBy(id=>id,StringComparer.Ordinal).Select(id=>new ClusterMemberFact(new ArchitectureTarget(ArchitectureTargetKind.GraphNode,id),1d))]));}var input=string.Join("\n",graph.Edges.OrderBy(e=>e.EdgeId,StringComparer.Ordinal).Select(e=>$"{e.SourceStableId}|{e.TargetStableId}|{e.EdgeKind}|{e.Confidence:R}"));var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(input))).ToLowerInvariant();return new(new ClusterRevisionFact(graph.Revision,"louvain",algorithmVersion,hash,facts),metrics);}
}
